def path(d,fill,stroke=None,w=2): return f'<path d="{d}" fill="{fill}"'+(f' stroke="{stroke}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round"' if stroke else '')+'/>'
def ellipse(x,y,rx,ry,fill,stroke=None,w=2): return f'<ellipse cx="{x}" cy="{y}" rx="{rx}" ry="{ry}" fill="{fill}"'+(f' stroke="{stroke}" stroke-width="{w}"' if stroke else '')+'/>'
def rect(x,y,w,h,c,r=0):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}"/>'
def line(x,y,a,b,c,w=2):return path(f'M{x} {y}L{a} {b}','none',c,w)
def group(s,x=0,y=0,scale=1,rotate=0):return f'<g transform="translate({x} {y}) scale({scale}) rotate({rotate})">{s}</g>'
def star(x,y,s,c):return path(f'M{x} {y-s}Q{x+2} {y-2} {x+s} {y}Q{x+2} {y+2} {x} {y+s}Q{x-2} {y+2} {x-s} {y}Q{x-2} {y-2} {x} {y-s}',c)
def cloud(x,y,s,c):return group(path('M-85 22C-118-4-87-41-56-27C-62-81 14-92 31-45C64-69 104-34 88-8C124 22 70 42 44 31L-57 36Q-85 38-85 22',c),x,y,s)
def moon(x,y,r,c):return path(f'M{x+r*.35} {y-r}C{x-r*1.2} {y-r*.6} {x-r*1.2} {y+r*.9} {x+r*.5} {y+r}C{x-r*.35} {y+r*.35} {x-r*.3} {y-r*.5} {x+r*.35} {y-r}',c)
def leaf(x,y,s,c,rot=0):return group(path('M0 0Q-34-25 0-67Q34-25 0 0',c)+line(0,0,0,-49,'#f8ebcc',1),x,y,s,rot)
def tree(x,y,s,c,accent):
 return group(path('M-8 0L-4-110L-23-149L-16-154L1-126L18-165L25-161L7-111L13 0',accent)+ellipse(0,-163,54,65,c)+ellipse(-33,-130,42,48,c)+ellipse(35,-140,44,47,c)+path('M0-20L0-172M0-95L-30-133M0-115L31-151','none','#f4dfb1',2),x,y,s)
def house(x,y,s,c,ink,roof):
 return group(rect(-28,-65,56,65,c,2)+path('M-40-63L0-100L40-63Z',roof,ink)+rect(-9,-27,18,27,ink,8)+rect(-19,-55,11,14,'#ffe4a6',1)+rect(9,-55,11,14,'#ffe4a6',1)+line(-14,-55,-14,-41,ink,1)+line(14,-55,14,-41,ink,1),x,y,s)
def boat(x,y,s,c,ink):
 return group(path('M-64 0L66 0L37 29L-36 29Z',c,ink)+line(0,-92,0,1,ink,3)+path('M-5-88L-5-8L-55-8Z','#f9eccc',ink)+path('M5-74L46-8L5-8Z','#eac78b',ink),x,y,s)
def fish(x,y,s,c,ink,rot=0):
 return group(ellipse(0,0,33,16,c,ink)+path('M-29 0L-53-20L-53 20Z',c,ink)+ellipse(19,-3,2,2,ink)+path('M5-10Q-6 0 5 10','none',ink),x,y,s,rot)
def bird(x,y,s,c):return group(path('M-40 0Q-10-44 0-11Q18-47 45-23Q19-11 7 8L-5 15L-16 6Z',c),x,y,s)
def stairs(x,y,s,c):
 return group(''.join(rect(-i*12,-i*16,30,17,c) for i in range(10)),x,y,s)
def flowers(x,y,s,ink,petal):
 return group(''.join(line(i*23,0,i*23-5,-28-(i%3)*10,ink,2)+ellipse(i*23-5,-35-(i%3)*10,9,8,petal)+ellipse(i*23-5,-35-(i%3)*10,3,3,'#f8e4a8') for i in range(-2,3)),x,y,s)
def balloon(x,y,s,c,ink):
 return group(path('M0-140C-90-140-80-45-24-10L24-10C80-45 90-140 0-140',c,ink)+path('M0-140Q-40-76-12-12M0-140Q40-76 12-12','none','#f9ebcb',3)+line(-24,-10,-15,24,ink)+line(24,-10,15,24,ink)+rect(-17,24,34,22,ink,4),x,y,s)
def bottle(x,y,s,c,ink,inside):
 return group(path('M-18-138L18-138L18-98Q56-75 56-44L56 44Q56 60 36 60L-36 60Q-56 60-56 44L-56-44Q-56-75-18-98Z',c,ink,3)+inside+rect(-22,-152,44,18,'#b17e57',3)+path('M-36-55L-36 31','none','#fff4d6',4),x,y,s)
def umbrella(x,y,s,c,ink):
 return group(path('M-87 0Q-76-78 0-82Q76-78 87 0Q66-18 44 0Q23-18 0 0Q-23-18-44 0Q-66-18-87 0',c,ink)+path('M0-81Q-38-40-44 0M0-81Q38-40 44 0M0-81L0 88Q-3 108-22 94','none',ink,3),x,y,s)

