def card_svg(n):
 sky,mid,ink,clay,gold=PALETTES[n%6];rng=random.Random(1701+n)
 defs=f'<defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="{sky}"/><stop offset="1" stop-color="{mid}"/></linearGradient><linearGradient id="hill" x2="0" y2="1"><stop stop-color="{mid}"/><stop offset="1" stop-color="{ink}"/></linearGradient><clipPath id="frame"><rect x="13" y="13" width="474" height="774" rx="29"/></clipPath></defs>'
 s=rect(0,0,500,800,'#f5e8cc',34)+defs+'<g clip-path="url(#frame)">'+rect(0,0,500,800,'url(#sky)')
 for _ in range(70):
  x=rng.randrange(20,480);y=rng.randrange(25,650);s+=ellipse(x,y,.6,.6,'#fff5dc')
 s+=ellipse(392 if n%2 else 108,146,52,52,gold)+cloud(90,225,.6,sky)+cloud(431,242,.65,sky)
 s+=path(f'M0 598Q120 {460+n%3*35} 260 578Q390 499 500 565L500 800L0 800Z',mid)+path('M0 665Q120 562 284 647Q385 602 500 671L500 800L0 800Z','url(#hill)')
 s+=scene(n,sky,mid,ink,clay,gold)
 s+=path('M0 731Q134 650 260 725Q374 674 500 731L500 800L0 800Z',ink)
 for i in range(12):
  x=20+i*43;y=752+(i%3)*13;s+=leaf(x,y,.26,mid,-24+(i%4)*17)
 s+='</g>'+f'<rect x="13" y="13" width="474" height="774" rx="29" fill="none" stroke="{gold}" stroke-width="2"/>'
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="500" height="800" viewBox="0 0 500 800"><title>{TITLES[n]}</title>{s}</svg>'

def render(name,svg,destination):
 master=MASTERS/(name+'.svg');master.parent.mkdir(parents=True,exist_ok=True);master.write_text(svg)
 destination.parent.mkdir(parents=True,exist_ok=True)
 cairosvg.svg2png(bytestring=svg.encode(),write_to=str(destination))

def svg(w,h,body):return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{body}</svg>'

def main():
 for n in range(36):render('cards/'+str(n),card_svg(n),ROOT/f'frontend/public/Cards/{n}.png')
 render('card-back',svg(500,800,rect(0,0,500,800,'#f7e8c8',30)+rect(18,18,464,764,'#486a78',24)+''.join(star(x,y,9,'#edc982') for x in range(55,490,65) for y in range(60,790,65))+ellipse(250,400,120,150,'#f2d99c','#fff2d3',4)+moon(250,400,82,'#486a78')+leaf(250,466,1.1,'#88b5a6',30)),ROOT/'frontend/public/Cards/card_reversed.png')
 # Original panoramic scenery: composition remains bright, layered and illustrated.
 for n,name in enumerate(['HomeBackground','GameBackground','LobbyBackground','SocialBackground','Achievements/AchievementsBackground']):
  sky,mid,ink,clay,gold=PALETTES[n];body='<defs><linearGradient id="bg" x2="0" y2="1"><stop stop-color="'+sky+'"/><stop offset="1" stop-color="'+mid+'"/></linearGradient></defs>'+rect(0,0,1600,1000,'url(#bg)')+ellipse(1230,222,110,110,gold)+cloud(220,230,2,sky)+cloud(1070,340,1.8,sky)+path('M0 650Q250 390 580 610Q850 393 1130 600Q1390 421 1600 570L1600 1000L0 1000Z',mid)+path('M0 770Q300 520 680 750Q1200 520 1600 760L1600 1000L0 1000Z',clay)+path('M0 925Q340 684 775 900Q1240 720 1600 910L1600 1000L0 1000Z',ink)
  body+=tree(150,819,2.9,ink,clay)+tree(1450,811,2.4,ink,clay)+house(1190,680,1.8,sky,ink,clay)+bird(742,202,1.6,ink)+bird(825,244,1.0,ink)+stairs(1030,742,1.4,gold)+flowers(349,903,2,ink,gold)
  render('backgrounds/'+name.replace('/','-'),svg(1600,1000,body),ROOT/f'frontend/src/static/images/{name}.png')
 # Own wordmark, drawn as vector letterforms rather than a licensed logo or font.
 letters=path('M30 30L30 170L80 170Q144 170 144 100Q144 30 80 30ZM57 55L80 55Q117 55 117 100Q117 145 80 145L57 145Z','#fcdf9b')+rect(178,30,27,140,'#fcdf9b')+path('M237 30L272 30L301 76L331 30L365 30L320 99L368 170L332 170L301 120L269 170L234 170L282 99Z','#fcdf9b')+rect(396,30,27,140,'#fcdf9b')+path('M453 30L568 30L568 56L525 56L525 170L496 170L496 56L453 56Z','#fcdf9b')
 word=svg(600,205,rect(8,9,584,185,'#3c626b',31)+letters+star(191,100,7,'#3c626b')+star(410,100,7,'#3c626b'))
 master=MASTERS/'wordmark.svg';master.write_text(word)
 png=ROOT/'frontend/src/static/images/Logo dixit.webp';png.unlink(missing_ok=True)
 cairosvg.svg2png(bytestring=word.encode(),write_to=str(png.with_suffix('.png')))
 emblem=svg(512,512,ellipse(256,256,244,244,'#f6dc9b','#456871',12)+ellipse(256,256,211,211,'#456871')+moon(250,245,123,'#f6dc9b')+leaf(272,347,1.6,'#8fbcad',40)+star(348,160,24,'#fff0c8')+star(340,295,15,'#fff0c8'))
 render('emblem',emblem,ROOT/'frontend/src/static/images/dixit round.png')
 for size in [192,512]:cairosvg.svg2png(bytestring=emblem.encode(),write_to=str(ROOT/f'frontend/public/logo{size}.png'),output_width=size,output_height=size)
 Image.open(ROOT/'frontend/public/logo192.png').save(ROOT/'frontend/public/favicon.ico',sizes=[(16,16),(32,32),(48,48)])
 parchment=svg(400,400,rect(0,0,400,400,'#f6e9cb',24)+''.join(line(20,y,380,y,'#ead6ad',1) for y in range(18,400,19)))
 render('parchment',parchment,ROOT/'frontend/src/static/images/icons/Parchment.png')
 fairy=svg(200,240,path('M95 110C-6 31-6 176 85 144C48 230 132 229 111 143C206 179 201 31 108 110','#eccd88','#4a6c73',4)+ellipse(101,129,10,36,'#4a6c73')+ellipse(101,84,13,13,'#4a6c73')+line(103,102,148,62,'#4a6c73',5)+star(153,56,14,'#d99d68'))
 render('fairy',fairy,ROOT/'frontend/src/static/images/icons/Fairy.png')
 locked=svg(200,200,ellipse(100,100,92,92,'#ead6ac','#52727a',4)+path('M65 89L65 66Q65 29 100 29Q135 29 135 66L135 89','none','#52727a',13)+rect(47,80,106,91,'#52727a',14)+ellipse(100,118,10,12,'#f8e8c4')+rect(96,125,8,19,'#f8e8c4'))
 render('locked',locked,ROOT/'frontend/src/static/images/Achievements/Locked.png')
 for family,levels in [('Play',[1,5,10,50]),('Win',[1,5,10,50]),('Trick',[5,20,50,100])]:
  for index,level in enumerate(levels):
   ink='#486b74';gold=['#d5a57d','#d7c5ab','#e5bd67','#b2cbbd'][index]
   body=path('M59 119L43 192L97 169L152 192L138 118Z',ink)+ellipse(100,84,76,76,gold,ink,4)+ellipse(100,84,61,61,'#fff0cf',ink,2)
   if family=='Play':body+=path('M70 49L70 122L130 85Z',ink)
   elif family=='Win':body+=path('M65 58L135 58L123 97Q100 120 77 97Z',ink)+rect(96,105,8,25,ink)+rect(81,127,38,8,ink)+path('M65 63Q35 59 53 89L75 95M135 63Q165 59 147 89L125 95','none',ink,5)
   else:body+=moon(99,84,37,ink)+star(124,66,12,gold)
   body+=''.join(star(70+i*20,157,5,ink) for i in range(index+1))
   render(f'badges/{family}{level}',svg(200,200,body),ROOT/f'frontend/public/Achievements/{family}Achievements/{family}{level}.png')
 manifest=[]
 for p in sorted(MASTERS.rglob('*.svg')):manifest.append({'master':str(p.relative_to(ROOT)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
 (MASTERS/'manifest.json').write_text(json.dumps({'license':'CC0-1.0','original_vector_art':True,'card_titles':TITLES,'masters':manifest},indent=2)+'\n')
 thumbs=Image.new('RGB',(1200,8*230),'#f6ecd7');draw=ImageDraw.Draw(thumbs)
 for n in range(36):
  im=Image.open(ROOT/f'frontend/public/Cards/{n}.png').convert('RGB');im.thumbnail((185,205));x=(n%6)*200+(200-im.width)//2;y=(n//6)*260
  # Contact sheet only; numbers are never present on game cards.
  thumbs.paste(im,(x,y));draw.text(((n%6)*200+6,y+209),f'{n}: {TITLES[n][:23]}',fill='#35505a')
 thumbs.crop((0,0,1200,1560)).save('/tmp/dixit-original-cards-contact.png')
 print('Generated 36 distinct narrative cards and all replacement visual assets; SVG masters retained')

if __name__=='__main__':main()
